return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Hungarian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:27+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'hu_HU','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" elmentve.','"%1$s" created. %2$d template updated.'=>'"%1$s" létrehozva. %2$d sablon frissítve.' . "\0" . '"%1$s" létrehozva. %2$d sablon frissítve.','"%s" created.'=>'"%s" létrehozva.','%d language not yet linked'=>'%d nyelv még nincs összekapcsolva' . "\0" . '%d nyelv még nincs összekapcsolva','%d link updated.'=>'%d link frissítve.' . "\0" . '%d link frissítve.','%d locale pack installed.'=>'%d helyi csomag telepítve.' . "\0" . '%d helyi csomag telepítve.','%d navigation reference updated.'=>'%d navigációs hivatkozás frissítve.' . "\0" . '%d navigációs hivatkozás frissítve.','%d part reference updated.'=>'%d rész hivatkozás frissítve.' . "\0" . '%d rész hivatkozás frissítve.','%s Archive'=>'%s archívum','(avg %.1f hits/block)'=>'(átlag %.1f találat/blokk)','(avg %.1f hits/entry)'=>'(átlag %.1f találat/bejegyzés)','(disabled)'=>'Letiltva','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} nem tartalmazható cserélhető linkeket — újra szkennelés a vizsgálathoz)','.txt file(s) in the directory'=>'.txt fájl(ok) a könyvtárban','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalizált sablon (ok) a „%2$s” témából megőrződtek az adatbázisban, de jelenleg inaktívak. Újra aktiválódnak, ha újraaktiválod azt a témát. Az új témához való fordításokat újra kell generálni a <strong>Beállítások → Lingua Forge → Router → FSE scaffold</strong> segítségével.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> automatikusan javítható link(ek)','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> link(ek), amelyek manuális felülvizsgálatot igényelnek','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> elavult útvonal(ak)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> sablonhiba(ák)','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Csak összerakott .mo fájlokat fogad el. A fájlnak követnie kell a {textdomain}-{locale}.mo} mintát. Egy meglévő fájl ugyanilyen nevével való feltöltés felülírja azt.','Action'=>'Akció','Actions'=>'Akciók','active'=>'aktív','Active Languages'=>'Aktív nyelvek','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktív nyelvek: adj hozzá minden támogatni kívánt nyelvet. Minden nyelvhez tartozik egy URL-előtag vagy aldomain, valamint egy hreflang címke a lap &lt;head&gt; részében.','Active Provider'=>'Aktív szolgáltató','Add entry'=>'Bejegyzés hozzáadása','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Adj utasításokat a vázlat javításához — pl. rövidebb legyen, adj hozzá összegző részt, használj formálisabb stílust, tartalmazzon GYIK blokkot…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Írjon utasításokat a vázlat javításához — pl. rövidítse, tegyen bele összegző részt, használjon formálisabb stílust…','Add new entry'=>'Új bejegyzés hozzáadása','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Adj egy kifejezést soronként. Mind a forráskifejezés, mind a célnyelvi megjelenítés kötelező. A nyelvpár határozza meg, mely fordítási feladatokra vonatkozik a korlátozás.','Adds a link to the home page so visitors can browse in their language.'=>'Hozzáad egy linket a főoldalhoz, így a látogatók böngészhetnek saját nyelvükön.','Administrators only (manage_options)'=>'Csak rendszergazdák (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Az elsődleges nyelv megváltoztatása után ürítse ki a permalinkeket (az alábbi szakaszban), hogy frissüljön az URL irányítás.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Miután megváltoztatta az URL-struktúra beállításait (útvonal előtag ↔ aldomain), mindig látogassa meg a Beállítások → Állandó linkek menüpontot, és kattintson a Mentés gombra az átírási szabályok ürítéséhez.','AI Behaviour Preset'=>'AI viselkedés előbeállítás','AI cache cleared. %d entry was removed.'=>'Az AI gyorsítótár törölve. %d bejegyzés lett eltávolítva.' . "\0" . 'Az AI gyorsítótár törölve. %d bejegyzés lett eltávolítva.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI Gy cache: felsorolja a gyorsított AI-válaszokat találatszámokkal. Tisztítsa meg az egész gyorsítótárat vagy egyetlen bejegyzés bejegyzéseit. Használja a "Tisztítás" gombot fordítási változtatás tesztelése előtt — a gyorsítótárban tárolt eredmények akkor is visszatérnek, amikor megváltoztatja az AI előbeállítást vagy modellt, amíg a gyorsítótár bejegyzése ki nem kerül.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Az AI funkciók opcionálisak. A nyelvi irányítás, hreflang, a nyelvváltó és a fordítási csoport rendszer mind működik, ha nincs beállítva szolgáltató.','AI Limits & Security'=>'AI Határok és Biztonság','AI provider returned an empty response.'=>'Az AI szolgáltató üres választ adott.','AI Usage'=>'AI használat','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Cél 120–160 karakter. Hagyd üresen, hogy a kivonat alapértelmezettként működjön.','All time'=>'Összes idő','Allow editors to lock individual blocks'=>'Engedélyezi a szerkesztőknek az egyes blokkok zárolását','Allow Gutenberg template-editing mode on post screens'=>'Engedélyezi a Gutenberg sablon szerkesztési módját a bejegyzés képernyőin','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Továbbá törli a nyelvi hozzárendeléseket, fordítási kapcsolatokat, meta leírásokat, glosszáriumot és Fordítási Memóriát, amikor a bővítményt eltávolítják.','Also generate meta description'=>'Meta leírás is generálása','Alternative (server-side):'=>'Alternatív (szerver oldali):','An unknown error occurred.'=>'Ismeretlen hiba történt.','and'=>'és','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'bármilyen','API calls saved by cache'=>'API hívások gyorsítótárazva','API Key'=>'API kulcs','API Keys'=>'API kulcsok','API Keys Tab'=>'API kulcsok lap','API Response Cache'=>'API válasz gyorsítótár','Applied ✓'=>'Alkalmazva ✓','Apply failed — please try again.'=>'Alkalmazás nem sikerült — kérjük, próbálja újra.','Apply to Block'=>'Alkalmazás a blokkra','Apply to Editor'=>'Alkalmazás a Szerkesztőben','Apply to Footnote'=>'Alkalmazás lábjegyzetre','Apply to Meta Description'=>'Alkalmazás a Meta leírására','Apply translation'=>'Fordítás alkalmazása','Applying…'=>'Alkalmazás…','Approximate size'=>'Körülbelüli méret','Archive'=>'Archívum','Archive: %s'=>'Archívum: %s','Authors and above (edit_published_posts)'=>'Szerzők és felette (szerkeszt_publikált_bejegyzések)','Behavior'=>'Viselkedés','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Viselkedés: válassza ki az AI előbeállítást (Szerint, Egyensúly, Kreatív), adjon hozzá oldal-átívelő egyedi utasításokat, engedélyezze vagy tiltsa le az automatikus bejegyzés mentése utáni fordítást, és konfigurálja a Fordítási Memóriát.','Block Content'=>'Blokk tartalom','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Udvarias értesítést jelenít meg, amikor az aktuális oldal az eredeti nyelvén jelenik meg, mert nincs fordítás a látogató nyelvéhez. A Lingua Forge router LINGUAFORGE_LANG_FALLBACK_ACTIVE jelzésétől függ — nem ad ki semmit, ha létezik fordítás a kérés nyelvéhez.','Block Editor'=>'Blokk szerkesztő','block keywordfallback'=>'helyettesítés','block keywordi18n'=>'i18n','block keywordlanguage'=>'nyelv','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'fordítás','Block locking'=>'Blokk zárolása','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'A saját bejegyzéstípusokra regisztrált blokk minták. Használd a Fordítás gombot egy nyelvi változat létrehozásához. A fordított tartalom itt van mentve, és másolható bármely CPT bejegyzésbe a blokk szerkesztő mintabehelyezőből vagy használható kiindulópontként egy Szinkronizált minta (Újrahasznosítható blokk) számára.','block titleMissing Translation Notice'=>'Hiányzó fordítás értesítés','Block translation reuses'=>'Blokk fordítási újrafelhasználások','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Blokk szintű fordítási gyorsítótár, amely megoszlik a bejegyzések között. Amikor engedélyezve van, az azonos blokkok (azonos markup, nyelvpár és szótár) a memóriából szolgálódnak ki, nem pedig újra hívják az AI-t. Konfigurálja a Beállítások → Viselkedés menüben.','Browser language redirect'=>'Böngésző nyelvi átirányítás','Built-in preset instructions:'=>'Beépített előre beállított utasítások:','Bulletize (•-prefixed)'=>'Felsorolás (•-el kezdve)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'A fordított egyezéseket cache-eli blokk szinten, így az újrafelhasználható tartalom (megosztott láblécek, oldalsávok, accordions, jogi szakaszok) nem fizet API-hívást minden alkalommal. Engedélyezve, a fordítási folyamat minden bejegyzést blokkokra bont, minden blokkot cache-ben keres, és csak a nem cache-elt blokkokat küldi az AI-nak egyetlen csoportos kérésben. A szójegyzék szerkesztése és a megfelelőségi előbeállítások automatikusan érvénytelenítik az érintett cache-elt fordításokat. Statisztikák megtekintése és a cache törlése a Karbantartás alatt.','cached'=>'gyorsítótárban','Cached API responses'=>'Gyorsítótárazott API válaszok','Cached block translations'=>'Gyorsítótárazott blokk fordítások','Cancel'=>'Mégse','Cannot determine target language from slug.'=>'Nem lehet meghatározni a célnyelvet a slug alapján.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Korlátozza, mennyit használhat az oldal AI-t, és korlátozza, mely felhasználói szerepkörök indíthatnak fizetős AI hívásokat. Ez a felhasználónkénti díjszabás (30 kérés / perc, beégetve) fölött helyezkedik el, amely már védi az egy felhasználótól származó futó ciklusokat.','chars'=>'karakterek','Chunk translated'=>'A tömb fordítva','Chunk translated to:'=>'A tömb fordítva: ','Clear'=>'Töröl','Clear All'=>'Összes törlése','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Törli az összes gyorsítótárazott AI eredményt? A jövőbeli kérések új API-hívásokat váltanak ki, amíg a gyorsítótár újraépül.','Clear API Response Cache'=>'API válasz gyorsítótárának törlése','Clear Debug Files'=>'Hibakereső fájlok törlése','Clear hints'=>'Tippjei törlése','Clear input'=>'Törölje a bemenetet','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Törli az összes Fordítási Memóriát? A jövőbeni fordítások újraépítik a gyorsítótárat, ahogy futnak.','Clear Translation Memory'=>'Fordítási memória törlése','Close'=>'Bezárás','Close language panel'=>'Nyelvi panel bezárása','Close popover'=>'Zárja be a felugró ablakot','Compliance Preset'=>'Megfelelőségi előbeállítás','Content generated'=>'Tartalom generálva','Content Generator'=>'Tartalom Generátor','Content ready'=>'Tartalom készen áll','Contributors and above — default (edit_posts)'=>'Hozzájárulók és felette — alapértelmezett (szerkesztés_bejegyzések)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Szabályozza, mennyi tartalmat küld az AI-nak, és mekkora lehet a válasz. Hagyja üresen a mezőt, hogy a beépített alapértelmezést használja (helykitöltőként mutatva). Növelje ezeket az értékeket, ha nagy oldalakat vágnak le; csökkentse őket az API költségek csökkentése érdekében.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Szabályozza az AI Tartalom Generátor funkció token költségvetését és bemeneti korlátait. Hagyja üresen a mezőket az alapértelmezett beállítások használatához.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Szabályozza, mi történik, amikor egy adminisztrátor eltávolítja a bővítményt a Bővítmények → Telepített bővítmények → Törlés menüpontban. A bővítmény beállításai és az AI gyorsítótárak mindig törlődnek. A nyelvi hozzárendeléseket és a fordítási kapcsolatokat alapértelmezés szerint megtartja, így véletlen eltávolítás vagy újratelepítés esetén ott folytathatja, ahol abbahagyta.','Conversational'=>'Beszélgetős','Copied ✓'=>'Másolva ✓','Copy'=>'Másolás','Copy markup'=>'Kód másolása','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Másolja az eredményt és illessze be, ahol szükséges (pl. közvetlenül a lábjegyzet mezőbe).','Copy to safe storage'=>'Másolás biztonságos tárolásba','Could not add entry: source term and target term are required.'=>'Nem sikerült hozzáadni a bejegyzést: szükséges a forrás és a cél kifejezés.','Could not copy the file. Check that the uploads folder is writable.'=>'Nem sikerült másolni a fájlt. Ellenőrizze, hogy a feltöltési mappa írható-e.','Could not instantiate the provider.'=>'Nem sikerült példányosítani a szolgáltatót.','Could not save the file. Check that the uploads folder is writable.'=>'Nem sikerült elmenteni a fájlt. Ellenőrizze, hogy a feltöltési mappa írható-e.','Could not save the glossary entry.'=>'Nem sikerült elmenteni a szójegyzék bejegyzést.','CPT Block Patterns'=>'CPT blokk minták','Create'=>'Létrehozás','Create missing'=>'Létrehozás hiányzik','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'A "%s" típusú bejegyzések fordításához aktív integráció szükséges. Kérjük, győződjön meg arról, hogy a szükséges integráció telepítve és aktív.','Creating…'=>'Létrehozás…','Creative / Marketing'=>'Kreatív / Marketing','Creative / Marketing instructions'=>'Kreatív / Marketing utasítások','Current content (will be overwritten)'=>'Jelenlegi tartalom (felülíródik)','Current title'=>'Jelenlegi cím','Current: {current}'=>'Jelenlegi: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Jelenleg az %s állandóból öröklött. Egy érték megadása itt felülírja azt.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Jelenleg kihagyva azoknál a bejegyzéseknél, amelyek blokk-kommentár attribútum helyettesítőket (wp:details összegző mezők stb.) használnak — ezek az eredeti egység hívásos fordítási útvonalra esnek.','Currently:'=>'Jelenleg:','Custom'=>'Egyéni','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Napi AI kvóta elérve (%1$d kérés). Újraindul %2$s UTC-kor.','Daily request limit'=>'Napi kéréslimit','Debug Files'=>'Hibakereső fájlok','Debug files cleared. %d file was removed.'=>'Hibakereső fájlok törölve. %d fájl lett eltávolítva.' . "\0" . 'Hibakereső fájlok törölve. %d fájl lett eltávolítva.','Debug logging'=>'Hibakereső naplózás','Debug logging disabled.'=>'Hibakereső naplózás letiltva.','Debug logging enabled.'=>'Hibakereső naplózás engedélyezve.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Hibakeresés: engedélyezze a hibakereső naplót, hogy rögzítse az AI utasításokat és az API válaszokat egy helyi fájlba. Kikapcsolás a hibakeresés után — a hibakereső mód minden AI kérésnél ír egy fájlt.','Delete'=>'Törlés','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Törli az összes .txt fájlt a hibakereső könyvtárban? A könyvtár maga megmarad, így a jövőbeni hibakereső írások még mindig ide kerülnek.','Delete all files for this override (both .mo and .po)?'=>'Törli az összes fájlt ehhez a felülíráshoz (mind .mo, mind .po)?','Delete content data on uninstall'=>'Tartalomadatok törlése az eltávolításkor','Delete this glossary entry?'=>'Törli ezt a szójegyzék bejegyzést?','Describe what to write — topic, key points, structure…'=>'Írjon le, mit írjon — téma, kulcspontok, szerkezet…','Directory'=>'Könyvtár','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Letiltás a prompt finomhangolásakor vagy amikor minden kérés el kell érje az AI szolgáltatót. A letiltás nem törli a gyorsítótárban lévő bejegyzéseket — az újra engedélyezés visszaállítja azokat. A letiltás az API költés azonnali növelését eredményezi forgalmas oldalakon.','Display'=>'Megjelenítés','Displays the Lingua Forge language switcher.'=>'A Lingua Forge nyelvváltó megjelenítése.','Documentation'=>'Dokumentáció','Done'=>'Kész','Done — {done} of {total} post(s) fixed.'=>'Kész — {done} a {total} bejegyzésből javítva.','Down'=>'Le','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Töltsd le és telepítsd a WordPress magnyelvi csomagot közvetlenül a WordPress.org-ról. A telepítés után a helyi nyelv elérhető lesz az URL útválasztáshoz és az AI fordítási munkafolyamathoz. A rendelkezésre álló nyelvek listája igény szerint frissül — kattints az alábbi gombra a betöltéshez.','Dropdown direction'=>'Legördülő irány','Editors and above (edit_others_posts)'=>'Szerkesztők és felette (szerkeszt_others_posts)','Enable API response caching'=>'API válasz gyorsítótár engedélyezése','Enable block-level translation cache reuse across posts'=>'Engedélyezi a blokk szintű fordítási cache újrafelhasználását bejegyzések között','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Adja meg az API kulcsát legalább egy AI szolgáltatóhoz. A kulcsokat titkosítva tároljuk AES-256-GCM titkosítással, egy oldal-specifikus titkos kulccsal (LINGUAFORGE_SECRET). Ne ossza meg az adatbázis exportokat anélkül, hogy először nem cseréli ki a titkos kulcsot.','environment variable'=>'környezeti változó','Error'=>'Hiba','Expand'=>'Bővítés','Expected: {expected}'=>'Várható: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Extra útmutatás — hangnem, stílus, korlátozások, célközönség…','Extra guidance — tone, style, constraints…'=>'Extra útmutatás — hangnem, stílus, korlátozások…','Failed. Please try again.'=>'Sikertelen. Kérjük, próbálja újra.','Feature'=>'Funkció','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'A funkciók két szintbe vannak csoportosítva. Adja meg pontosan az egyes szintek és szolgáltatók modell azonosítóját. Hagyjon üresen egy mezőt, hogy a beépített alapértelmezést használja (amelyet helykitöltőként mutatunk). Csak az aktív szolgáltató modelljei hívódnak meg futásidőben — a többit előre konfigurálja, ha váltani kíván.','File copied to safe storage successfully.'=>'A fájl sikeresen másolva a biztonságos tárolásba.','Files'=>'Fájlok','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'A fájlok az alábbi könyvtárba kerülnek. Hasznos fordítási problémák diagnosztizálásához — kapcsold ki, miután megvan, amire szükséged van, hogy a fájlok ne halmozódjanak. Ezt a wp-config.php fájlból is kényszerítheted a `define( \'LINGUAFORGE_AI_DEBUG\', true );` sorral, ami felülírja ezt a kapcsolót.','Filter'=>'Szűrő','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Szűrő a linguaforge_debug_dir segítségével, hogy a hibakereső kimenetet nem nyilvános helyre irányítsd.','Fix'=>'Javítás','Fix All'=>'Összes javítása','Fix all links'=>'Minden link javítása','Fix all parts'=>'Minden rész javítása','Fix Links'=>'Hivatkozások javítása','Fix Nav'=>'Navigáció javítása','Fix Parts'=>'Részek javítása','Fix Template'=>'Sablon javítása','Fixing {n} / {total}…'=>'Javítás {n} / {total}…','Fixing…'=>'Javítás…','Flush Permalink Rules'=>'Permalink szabályok ürítése','Flush Permalinks'=>'Permalinkek ürítése','Footnote Content'=>'Lábjegyzet tartalma','footnote(s) translated — applied together with content.'=>'Fordított lábjegyzet(ek) — a tartalommal együtt alkalmazva.','Footnotes'=>'Lábjegyzetek','Footnotes payload (advanced)'=>'Lábjegyzetek payload (fejlett)','Forbidden'=>'Tiltott','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Kényszerítve KI a wp-config.php fájlban a LINGUAFORGE_AI_DEBUG állandó által. Töröld ezt a sort, hogy innen irányítsd ezt a kapcsolót.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Kényszerítve BE a wp-config.php fájlban a LINGUAFORGE_AI_DEBUG állandó által. Töröld ezt a sort, hogy innen irányítsd ezt a kapcsolót.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Talált {parts} a <strong>{total}</strong> összesen <strong>{scanned}</strong> átvizsgált bejegyzés között a <strong>{lang}</strong> nyelven.','From'=>'Innen','Front Page'=>'Főoldal','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE lokalizáció: keret, fordítás és linkek javítása a Full Site Editing sablonokban és sablonrészekben közvetlenül ebből a lapból.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Az aktív téma által elindított FSE sablonok. Hozd létre, majd testreszabhatod a Webhely Szerkesztőben.','Full Article'=>'Teljes cikk','Full post'=>'Teljes bejegyzés','General'=>'Általános','Generate'=>'Létrehozás','Generate Content'=>'Tartalom generálása','Generate content…'=>'Tartalom generálása…','Generate Excerpt'=>'Kivonat generálása','Generate Meta Description'=>'Meta leírás generálása','Generated Content'=>'Generált tartalom','Generated meta description'=>'Generált meta leírás','Generating…'=>'Generálás…','Generation failed.'=>'A generálás nem sikerült.','Getting started'=>'Elindulás','Global AI preset'=>'Globális AI előbeállítás','Global default (%s)'=>'Globális alapértelmezett (%s)','Glossary'=>'Szójegyzék','Glossary entry added.'=>'Szójegyzék bejegyzés hozzáadva.','Glossary entry removed.'=>'Szójegyzék bejegyzés eltávolítva.','Glossary Tab'=>'Szótár lap','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Elrejtés','Hints'=>'Tipp','Home link text'=>'Főoldal link szövege','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Hogyan kell megjelennie a fordításban. Írja be ugyanazt az értéket, mint a forrás kifejezés, hogy az AI megőrizze szó szerint.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Ikon + címke','Icon only'=>'Csak ikon','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Ha be van jelölve, a bővítmény eltávolítása véglegesen törli az összes nyelvi hozzárendelést, fordítási kapcsolatot, meta leírást, oldalspecifikus előbeállításokat, az AI glosszáriumot és a Fordítási Memóriát minden bejegyzéshez ezen az oldalon. Ez nem vonható vissza. Hagyja üresen, hacsak nem teljesen távolítja el a többnyelvű támogatást az oldalról.','Improve writing'=>'Írás javítása','Informative'=>'Tájékoztató','Input tokens'=>'Bemeneti tokenek','Install'=>'Telepítés','Install a Language'=>'Nyelv telepítése','Installing…'=>'Telepítés…','Instructions (optional)'=>'Utasítások (opcionális)','Instructions / key points'=>'Utasítások / kulcspontok','Integration API'=>'Integrációs API','Internal Link Fixer'=>'Belső hivatkozás javító','Introduction only'=>'Csak bevezető','Invalid file reference.'=>'Érvénytelen fájl hivatkozás.','Invalid filename.'=>'Érvénytelen fájl név.','Invalid language.'=>'Érvénytelen nyelv.','Invalid locale code.'=>'Érvénytelen helyi kód.','Invalid or primary language.'=>'Érvénytelen vagy elsődleges nyelv.','Invalid post type.'=>'Érvénytelen poszt típus.','Invalid template part.'=>'Érvénytelen sablonrész.','Invalid template type.'=>'Érvénytelen sablon típus.','Key points, ideas, or structure to build from…'=>'Fő pontok, ötletek vagy szerkezet, amiből kiindulhatunk…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'A kulcsokat AES-256-CBC titkosítással tárolják a WordPress adatbázisban. A titkosítás titkos kulcsa a WordPress hitelesítési sóiból származik (wp-config.php), így a tiszta szövegű kulcsok soha nem kerülnek az adatbázisba.','Language'=>'Nyelv','Language %s installed successfully.'=>'A %s nyelv sikeresen telepítve.','Language (optional)'=>'Nyelv (opcionális)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'A nyelvi telepítés le van tiltva ezen a szerveren (DISALLOW_FILE_MODS van beállítva).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'A nyelvi telepítés le van tiltva ezen a szerveren. A DISALLOW_FILE_MODS állandó beállítás van a wp-config.php fájlban. Telepíts nyelvi csomagokat manuálisan WP-CLI segítségével: wp language core install de_DE','Language label'=>'Nyelvi címke','Language Overrides'=>'Nyelvi felülírások','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Nyelvi felülírások: kezelje a testreszabott .po/.mo felülíró fájlokat a Lingua Forge UI szövegeihez. Használja ezt ahelyett, hogy közvetlenül szerkesztené a bővítmény fájljait — a felülírások megmaradnak a frissítések során.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'A nyelvi csomag telepítése sikertelen. A nyelv már telepítve lehet, a helyi kód helytelen lehet, vagy a szervered blokkolja a fájlírást.','Language Setup'=>'Nyelvi beállítás','Language Switcher'=>'Nyelvváltó','Language switcher'=>'Nyelvváltó','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'A téma nyelvspecifikus példányai. Miután felépült, a sablonokat frissítik, hogy hivatkozzanak a nyelvspecifikus részre.','Language:'=>'Nyelv:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'A router által jelenleg ismert nyelvek (a telepített WordPress helyi csomagokból és a fő nyelvből származnak). Telepíts további nyelvi csomagokat az alábbi szakaszban, hogy több nyelvet tegyél elérhetővé az útválasztáshoz és fordításhoz.','Last 30 days'=>'Az elmúlt 30 nap','Last 7 days'=>'Az elmúlt 7 nap','Lead paragraph (≤60 w)'=>'Bevezető bekezdés (≤60 szó)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Hagyjon üresen egy modellszámot, hogy a beépített alapértelmezést használja az adott szinthez. A helyőrző szöveg mutatja, melyik modellt fogja használni.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Hagyja üresen a márkanevek és nyelvfüggetlen kifejezések esetében, amelyeket minden fordításban meg kell tartani.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Hagyja üresen, hogy ezt a bejegyzést minden célnyelvre alkalmazza — ideális márkanevekhez, rövidítésekhez és olyan kifejezésekhez, amelyeket szó szerint meg kell tartani minden fordításban.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Hagyja üresen, hogy megtartsa a meglévő kulcsot. Adjon meg egy új értéket a helyettesítéshez.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Hagyja üresen az alapértelmezett használatához. A mentett felülírás törlése a következő mentéskor visszaállítja az alapértelmezettet.','Legal / Compliance'=>'Jogi / Megfelelőség','Legal / Compliance instructions'=>'Jogi / Megfelelőségi utasítások','Light'=>'Könnyű','Light (default — fast and cost-effective)'=>'Könnyű (alapértelmezett — gyors és költséghatékony)','Light (fast and cost-effective — Haiku / Flash)'=>'Könnyű (gyors és költséghatékony — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Fény: meta leírások és kivonatok generálására — gyors, alacsony költségű.','Limit results to pages in the given Lingua Forge language code.'=>'Eredmények szűkítése a megadott Lingua Forge nyelvkód oldalaira.','Limits'=>'Határok','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'A Lingua Forge többnyelvű irányítást, AI-alapú fordítást, hreflang SEO címkéket és nyelvváltót ad a WordPress oldalához.','Lingua Forge AI Tools'=>'Lingua Forge AI eszközök','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'A Lingua Forge alapértelmezés szerint két Gutenberg funkciót korlátoz, hogy az szerkesztési viselkedés egységes maradjon a nyelvek között. Itt választhat, ha teljes Gutenberg / FSE képességekre van szüksége.','Lingua Forge Settings'=>'Lingua Forge beállítások','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'A Lingua Forge két független gyorsítótár réteget használ, hogy elkerülje az ismételt AI API hívásokat. Használja az alábbi lapokat mindegyik ellenőrzéséhez és kezeléséhez.','Lingua Forge uses two model tiers per provider:'=>'A Lingua Forge két modell szintet használ szolgáltatónként:','Lingua Forge — Quick Translate'=>'Lingua Forge — Gyors Fordítás','Lingua Forge — Settings'=>'Lingua Forge — Beállítások','link(s)'=>'link(ek)','Links'=>'Linkek','Load available languages'=>'Töltsd be az elérhető nyelveket','Loading…'=>'Betöltés…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'A Loco Translate a saját fordításait a wp-content/languages/loco/ helyen tárolja — ez a helyszín csendben törölhető egy WP magfrissítés, bővítmény újratelepítés vagy a Loco Translate eltávolítása esetén. A fájlok ide való másolásával azok átkerülnek a Lingua Forge i18n-overrides könyvtárba, amely minden ilyen eseményen túléli, és automatikusan betöltődik minden kérésnél.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Másolás biztonságos tárolásba','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'A legalacsonyabb WordPress képesség, amely lehetővé teszi az AI funkciók indítását. Ennek szigorítása több szerzős oldalakon megakadályozza, hogy a Hozzájárulók vagy próbafiókok fizetős AI hívásokat futtassanak. Felülírható az egyes funkciók esetében a linguaforge_required_capability szűrő segítségével.','Maintenance'=>'Karbantartás','Maintenance Tab'=>'Karbantartási lap','Make casual'=>'Informálisra alakítás','Make concise'=>'Rövidítés','Make formal'=>'Formálisra alakítás','Mark citations needed'=>'Hivatkozások szükségességének jelölése','Max context characters'=>'Max. kontextus karakterek','Max hints characters'=>'Max. tipp karakterek','Max input characters'=>'Maximális bemeneti karakterek','Max output tokens'=>'Maximális kimeneti tokenek','Maximum characters accepted from the input field. Default: 8 000.'=>'A bemeneti mezőből elfogadott maximális karakterek száma. Alapértelmezett: 8000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'A meglévő poszt tartalmának maximális karakterei, amelyeket az AI seed kontextusként kap, ha nem ad meg Hint-et. Alapértelmezett: 6000.','Maximum characters read from the Hints field. Default: 2 000.'=>'A Hint mezőből olvasott maximális karakterek száma. Alapértelmezett: 2000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximum számú karakter a poszt tartalmából, amit az AI-hoz továbbítanak. 0 azt jelenti, hogy nincs korlátozás — a teljes tartalom mindig elküldésre kerül (ajánlott). Állítson be nem nulla értéket csak akkor, ha a szolgáltatója szigorú kontextusablakkal rendelkezik. Figyelmeztetés kerül kiírásra a PHP hibajegyzékbe, amikor a tartalmat levágják.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'A maximális tokenek száma, amelyet az AI egy fordítási válaszban előállíthat. Ha a fordítás csendben megszakad a végén, növelje ezt az értéket. Alapértelmezett: 16 000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'A maximális tokenek száma, amit az AI generálhat egy generálási futás során. Növelje, ha a teljes cikkek levágódnak. Alapértelmezett: 8192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'A maximális tokenek száma, amit az AI generálhat gyors fordításonként. Alapértelmezett: 2000.','Meta Description'=>'Meta leírás','Meta Description, Excerpt Generator'=>'Meta leírás, kivonat generátor','Minimum role'=>'Minimum szerepkör','Missing pattern name or language.'=>'Hiányzik a minta neve vagy nyelv.','Mode'=>'Mód','Model'=>'Modell','Model tier'=>'Modell szint','Models'=>'Modellek','Models Tab (General)'=>'Modellek lap (Általános)','Most recent cached block'=>'Legutóbbi gyorsított blokk','Most recent cached response'=>'Legutóbbi gyorsított válasz','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Többnyelvű útvonalkezelés, SEO meta címkék és AI tartalom eszközök WordPresshez. Kombinálja a nyelvfelismerést, URL útvonalkezelést, hreflang-et, meta leírásokat, valamint AI-alapú kivonat, meta és fordítási funkciókat.','Name displayed in this language. Leave empty to use the source name.'=>'A név ebben a nyelvben megjelenítve. Hagyja üresen a forrásnév használatához.','Navigation'=>'Navigáció','Navigation has no content to translate.'=>'A navigációnak nincs tartalma a fordításhoz.','Navigation not found.'=>'Navigáció nem található.','Navigation posts are translated via the Router tab, not this button.'=>'A navigációs bejegyzéseket a Router fülön fordítják, nem ezen a gombon.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'A navigáció fordításához aktív AI szolgáltató szükséges. Állíts be API kulcsot az API kulcsok fülön.','Navigations'=>'Navigációk','Network error — could not reach the WordPress AJAX endpoint.'=>'Hálózati hiba — nem lehet elérni a WordPress AJAX végpontot.','No %s version found in this translation group.'=>'Nincs "%s" verzió ebben a fordítási csoportban.','No AI provider configured.'=>'Nincs AI szolgáltató konfigurálva.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nincs AI használat a kiválasztott ablakban (%s). Válasszon szélesebb időintervallumot fent.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Még nem rögzített AI használat. Amint egy szerkesztő fordítást futtat, meta leírást generál, vagy bármilyen más AI funkciót használ, az összesítések itt jelennek meg.','No API key configured for this provider.'=>'Nincs API kulcs konfigurálva ehhez a szolgáltatóhoz.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Nincs beépített utasítás — minden AI funkció saját hangolt alapértelmezéseket használ. Töltse ki az alábbi Egyéni prompt utasítások mezőt, hogy saját szabályokat adjon hozzá az oldal egészére.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Még nem találhatók egyedi Loco Translate fájlok. Ezek itt jelennek meg, amint elment egy fordítást a Loco Translate-ben.','No file was selected.'=>'Nem választott ki fájlt.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Jelenleg nincs egyező szójegyzék bejegyzés a szűrővel. Törölje a szűrőt, hogy minden bejegyzést lásson, vagy adjon hozzá újat az alábbiakban.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Még nincs szójegyzék bejegyzés. Adjon hozzá egyet az alábbiakban, hogy elkezdje a terminológia érvényesítését a fordításokban.','No internal links found to update.'=>'Nem található belső hivatkozás frissítésre.','No language-specific template parts found to map.'=>'Nem található nyelvspecifikus sablonrész a térképezéshez.','No navigation references needed updating.'=>'Nincs szükség navigációs hivatkozás frissítésére.','No override files uploaded yet.'=>'Még nem töltött fel felülíró fájlokat.','No response from provider — check the error log for details.'=>'Nincs válasz a szolgáltatótól — ellenőrizze a hibajegyet a részletekért.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Nincs másodlagos nyelv konfigurálva. Telepíts egy nyelvi csomagot fent, hogy engedélyezd a sablon vázlatokat.','No source content found to translate.'=>'Nem található forrástartalom a fordításhoz.','No source page linked yet.'=>'Még nincs összekapcsolva forrásoldal.','No template part references needed updating.'=>'Nincs szükség hivatkozás frissítésére a sablonrészben.','No {lang} translation registered (TRID missing)'=>'Nincs {lang} fordítás regisztrálva (TRID hiányzik)','Notes'=>'Megjegyzések','Notice message'=>'Értesítési üzenet','Notice settings'=>'Értesítési beállítások','Oldest cached block'=>'Legrégebbi gyorsított blokk','Oldest cached response'=>'Legrégebbi gyorsított válasz','Only .mo files are accepted.'=>'Csak .mo fájlokat fogadunk el.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Opcionális kontextus szerkesztők számára (pl. "ASIC = Application-Specific Integrated Circuit; megőrizni angolul technikai kontextusban").','Output'=>'Kimenet','Output tokens'=>'Kimeneti tokenek','overridden'=>'felülírt','Override file deleted.'=>'A felülíró fájl törölve.','Override file uploaded successfully.'=>'A felülíró fájl sikeresen feltöltve.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Felülírja az AI előbeállítást a fordítás és tartalomgenerálás esetén ezen az oldalon. Minden más funkció mindig az általános előbeállítást használja.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Felülírja az AI előbeállítást a fordítás és tartalomgenerálás esetén ezen az oldalon. A webhely-szerte egyéni prompt utasítások (Beállítások → Viselkedés) mindig hozzáadódnak minden kéréshez, függetlenül ettől a választástól.','Overview'=>'Áttekintés','Page'=>'Oldal','Part'=>'Rész','Paste a footnote, sentence, or any snippet here…'=>'Illessze ide lábjegyzetet, mondatot vagy bármilyen szövegrészletet…','Paste text, or select text in the editor first…'=>'Illessze be a szöveget, vagy először jelölje ki a szöveget a szerkesztőben…','Paste text, or select text on the page first…'=>'Illessze be a szöveget, vagy először jelölje ki a szöveget az oldalon…','Paste your API key…'=>'Illessze be az API kulcsát…','Path prefix — example.com/de/'=>'Útvonal előtag — example.com/de/','Pattern'=>'Minta','Pattern has no content to translate.'=>'A minta nem tartalmaz fordítandó tartalmat.','Pattern not found.'=>'Minta nem található.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'A minta lefordítva és elmentve. Másolja a tartalmat a CPT bejegyzésébe a blokk szerkesztő mintabeillesztő segítségével, vagy használja kiindulópontként újrahasználható blokkhoz.','Pattern translation failed.'=>'A minta fordítása sikertelen volt.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Az AI által generált fordítások, meta leírások, kivonatok és tartalom oldalankénti gyorsítótára. Mindig aktív — nincs külön kapcsoló. A bejegyzések tartalmának vagy az AI szolgáltatónak/modellnek a változásakor automatikusan érvénytelenítve. Használja a "↺ Újrafordítás" gombot vagy a Törlés gombot az alatta az új API hívás kényszerítéséhez.','Permalink rules flushed successfully.'=>'Permalink szabályok sikeresen ürítve.','Permission denied.'=>'Engedély megtagadva.','Persuasive'=>'Meggyőző','PHP constant'=>'PHP állandó','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Jelölje ki azokat a kifejezéseket, amelyeket nem szabad fordítani vagy mindig bizonyos módon kell megjeleníteni (pl. márkanevek, terméknevek, rövidítések). A szótár korlátozásokat minden AI fordítási kérésbe beépítjük: bejegyzés fordítás, meta leírás, kivonat és FSE sablon fordítás.','Plain language'=>'Egyszerű nyelvezet','Please enter some instructions first…'=>'Kérjük, írjon be néhány utasítást először…','Please enter some text first…'=>'Kérjük, írjon be néhány szöveget először…','Post'=>'Bejegyzés','Post not found.'=>'A bejegyzés nem található.','Post Types'=>'Bejegyzéstípusok','Prefilled from excerpt. Edit to override.'=>'Előre kitöltve a kivonatból. Szerkeszd a felülíráshoz.','Primary Language'=>'Elsődleges nyelv','Primary language'=>'Elsődleges nyelv','Primary language saved.'=>'Elsődleges nyelv mentve.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Elsődleges nyelv: az a nyelv, amelyen a meglévő tartalma íródott. Minden fordítás ebből a nyelvből készül; ennek megváltoztatása nem mozgat vagy töröl bejegyzéseket.','Processing…'=>'Feldolgozás…','Provider'=>'Szolgáltató','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'A szolgáltató nem adott vissza szöveget. Ellenőrizze a WordPress hibajegyzékét a részletes hiba okáért.','Quality'=>'Minőség','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Minőség (alapértelmezett — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Minőség (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Minőség: a bejegyzés fordítására és tartalomgenerálásra használva — magasabb minőség, magasabb költség.','Quick Translate'=>'Gyors fordítás','Quick Translation'=>'Gyors fordítás','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'A Gyors fordítás a snippet/chunk módban használható — rövid szakaszok fordítása kérésre az eszköztárról, szerkesztőről vagy blokk felugró ablakokból. Külön, könnyebb konfigurációt használ a teljes oldal fordításától, hogy a válaszok gyorsak és költséghatékonyak maradjanak.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Újra engedélyezi Gutenberg canLockBlocks funkcióját. Hasznos szerkesztői sablonokhoz, amelyek megakadályozzák a hozzájárulók számára, hogy bizonyos blokkokat mozgatni vagy törölni tudjanak.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Újra engedélyezi a supportsTemplateMode funkciót. Alapvető a teljes webhely szerkesztési munkafolyamatokban, ahol szándékosan vannak bejegyzés szintű sablon felülírások.','Re-generates and updates the cached result.'=>'Újra generálja és frissíti a gyorsítótárban lévő eredményt.','Re-scan'=>'Újra szkennelés','Re-scanning…'=>'Újra vizsgálás…','Re-translate'=>'Újrafordítás','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Átirányítja a látogatókat a böngésző Accept-Language fejléc alapján a preferált nyelvükre','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Tovább finomítás — pl. "rövidebbre vágás" vagy "formális hangnem használata"…','Refine further:'=>'Tovább finomítás:','Refinement'=>'Finomhangolás','Refinement failed — please try again.'=>'A finomhangolás nem sikerült — kérjük, próbálja újra.','Refining…'=>'Finomhangolás…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Újra generálja a WordPress átírási szabályokat, így az URL előtagok, nyelvspecifikus slugok és archívum átírások összhangban lesznek. Szükséges a fő nyelv megváltoztatása vagy új nyelvi támogatás hozzáadása után.','Remove stored key'=>'Tárolt kulcs eltávolítása','Report an issue on GitHub'=>'Hiba jelentése a GitHubon','Request failed — please try again.'=>'A kérés nem sikerült — kérjük, próbálja újra.','Request failed.'=>'A kérés nem sikerült.','Request failed. Check your connection.'=>'A kérés nem sikerült. Ellenőrizze a kapcsolatot.','Request failed. Please try again.'=>'A kérés nem sikerült. Kérjük, próbálja újra.','Requests'=>'Kérések','Reset'=>'Visszaállítás','Result will appear here…'=>'Az eredmény itt jelenik meg…','Retranslate'=>'Újrafordítás','Retranslating…'=>'Újrafordítás…','Review carefully — links and slugs not updated.'=>'Alapos áttekintés — linkek és slugok nem frissültek.','Review translation before applying'=>'Áttekintés a fordításról az alkalmazás előtt','Revise'=>'Áttekintés','Revision'=>'Átdolgozás','Revision Type'=>'Átdolgozás típusa','Router'=>'Útválasztó','Router Tab'=>'Router lap','Save Debug Setting'=>'Hibakereső beállítás mentése','Save Router Settings'=>'Router beállítások mentése','Save Settings'=>'Beállítások mentése','Save the post to persist changes.'=>'Mentse a bejegyzést a változások mentéséhez.','Save Uninstall Setting'=>'Mentés az eltávolítási beállításokhoz','Saved to the meta description field when you apply.'=>'Mentve a meta leírás mezőbe, amikor alkalmazod.','Scan failed: '=>'Szkennelés sikertelen: ','Scan request failed. Please try again.'=>'A szkennelési kérés sikertelen. Kérjük, próbálja újra.','Scanning posts for broken language links…'=>'Posztok vizsgálata hibás nyelvi linkekért…','Search'=>'Keresés','Search Results'=>'Keresési eredmények','Security check failed — file path is not permitted.'=>'Biztonsági ellenőrzés sikertelen — a fájl útvonala nem megengedett.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Válassz egy nyelvet a FSE sablonok, sablonrészek és navigációs menük kezeléséhez.','Select language'=>'Válasszon nyelvet','SEO character-count info'=>'SEO karakter-szám információ','Server setup (subdomain)'=>'Szerver beállítás (aldomain)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Beállítja az alapértelmezett AI viselkedést az összes funkcióhoz az oldal egészén. Egyes bejegyzések felülírhatják ezt a Fordítás és Tartalom Generálás esetén a Lingua Forge meta dobozban.','Settings'=>'Beállítások','Settings saved.'=>'A beállítások mentve.','Show home link'=>'Főoldal link megjelenítése','Shown when no translation exists for the visitor\'s language.'=>'Amikor nincs fordítás a látogató nyelvéhez, megjelenik.','Single'=>'Egyedi','Single %s'=>'Egység %s','Single: %s'=>'Egység: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Az oldal egészére vonatkozó plafon az AI kérésre UTC nap szerint (mind a Toolbar fordításokat, mind a blokk módosításokat számítva). A számláló UTC éjfélkor nullázódik. Állítsa 0-ra a letiltáshoz.','Size'=>'Méret','Some link fixes failed.'=>'Néhány link javítása sikertelen volt.','Some nav ref fixes failed.'=>'Néhány navigációs hivatkozás javítása sikertelen volt.','Some part fixes failed.'=>'Néhány rész javítása sikertelen volt.','Some parts could not be created.'=>'Néhány részt nem sikerült létrehozni.','Some templates could not be created.'=>'Néhány sablont nem sikerült létrehozni.','Some translations failed.'=>'Néhány fordítás sikertelen volt.','Source file not found.'=>'A forrásfájl nem található.','Source lang'=>'Forrás nyelv','Source language'=>'Forrás nyelv','Source term'=>'Forrás kifejezés','Standard'=>'Alapértelmezett','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'A Standard minden funkció saját hangolt hőmérsékletet használ: Fordítás T=0.2 (pontos), Gyors fordítás T=0.4, Tartalom generátor T=0.6 (kreatív). A többi előbeállítás egységesen alkalmaz egy fix hőmérsékletet minden funkciónál.','Status'=>'Állapot','Status / Actions'=>'Állapot / Akciók','Storytelling'=>'Történetmesélés','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Szigorú megőrzési mód jogi, szabályozási, orvosi vagy technikai tartalomhoz. Amikor be van kapcsolva, minden AI funkció alacsony mintavételi hőmérsékletet használ, és a rendszer kéréséhez hozzáfűzi az alábbi kiegészítést — a terminológia, cikk számok, egységek, márkanevek és szabályozási nyelv szó szerint megőrzött, nem parafrazált.','Structured Outline'=>'Strukturált vázlat','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Az aldomain módja megköveteli, hogy a webkiszolgálód minden nyelvi aldomaint (pl. de.example.com) erre a WordPress telepítésre mutasson. A módváltás után ürítsd ki a permalink szabályokat és töröld a cache-eket. Ha a fő URL tartalmazza a www-t (pl. www.example.com), használd az lf_base_domain szűrőt az egyszerű csúcs domain beállításához, hogy az aldomének helyesen legyenek kialakítva.','Subdomain — de.example.com/'=>'Aldomain — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Támogatott szolgáltatók: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Csak egy szolgáltató lehet aktív egyszerre. Válassza ki az aktív szolgáltatót az Általános lapon.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, funkciónként','Target lang'=>'Cél nyelv','Target Language'=>'Cél nyelv','Target language'=>'Cél nyelv','Target term'=>'Cél kifejezés','Target: 140–160 chars for optimal SERP display'=>'Cél: 140–160 karakter a optimális SERP megjelenítéshez','Technical'=>'Technikai','Technical / Scientific'=>'Technikai / Tudományos','Technical / Scientific instructions'=>'Technikai / Tudományos utasítások','Template "%s" already exists.'=>'A "%s" sablon már létezik.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'A "{expected}" sablon nem létezik — először hozd létre a Webhely Szerkesztőben.','Template has no content.'=>'A sablonnak nincs tartalma.','Template mode'=>'Sablon mód','Template not found or not stored in the database.'=>'Sablon nem található vagy nincs az adatbázisban tárolva.','Template part "%s" already exists.'=>'A "%s" sablonrész már létezik.','Template part has no content.'=>'A sablonrésznek nincs tartalma.','Template part not found or not stored in the database.'=>'Sablonrész nem található vagy nincs az adatbázisban tárolva.','Template Parts'=>'Sablonrészek','Templates'=>'Sablonok','Test connection'=>'Kapcsolat tesztelése','Testing…'=>'Tesztelés…','Text domain / locale'=>'Szöveg domain / hely','Text to translate'=>'Fordítandó szöveg','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Az API válasz gyorsítótár tárolja minden AI kérés nyers eredményét — fordítás, meta leírás, kivonat és tartalom generálás — a bemenetek hash értéke szerint (tartalom, nyelvpár, szolgáltató, modell). A későbbi kérdések azonos bemenetekkel a gyorsítótárból szolgálódnak ki API hívás nélkül. A gyorsítótár különbözik a Fordítási Memóriától: a Fordítási Memória blokk szinten működik és megoszlik a bejegyzések között; az API válasz gyorsítótár blokk szinten működik és bejegyzésenként van kulcsolva.','The editor did not accept the content — please try again.'=>'A szerkesztő nem fogadta el a tartalmat — kérjük, próbálja újra.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'A Könnyű szint a gyors modellt használja, amely a fent említett Modellek táblában van konfigurálva (alapértelmezett: Haiku / Flash). Válts a Minőségre, ha ugyanazt a fordítási pontosságot szeretnéd elérni, mint a teljes oldal módban a snippet-ekhez.','The phrase as it appears in the source text.'=>'A kifejezés, ahogyan a forrásszövegben megjelenik.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Az elsődleges nyelvet mindig a webhely gyökérben szolgálja ki — nincs URL előtag útvonal módban, nincs nyelvi aldomain al-módban. Minden más nyelv vagy a /lang/ útvonal előtagot (pl. example.com/de/) vagy nyelvi aldomaint (pl. de.example.com) használ, az alábbi URL-struktúra beállítástól függően.','The source page has no footnotes.'=>'A forrásoldalnak nincsenek láblécei.','The upload failed — please try again.'=>'A feltöltés sikertelen volt — próbálja újra.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Ezek a láblécek a forrásoldalról származnak, és csak hivatkozásként jelennek meg itt. Add hozzá őket a blokk szerkesztő segítségével.','This is the source page. Footnotes are edited directly in the block editor.'=>'Ez a forrásoldal. Láblécek közvetlenül a blokk szerkesztőben szerkeszthetők.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Ez a kulcs jelenleg egy szerver által biztosított %s, és nem távolítható el itt. Adjon meg egy új kulcsot fent, hogy felülírja az adatbázis értékével.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tipp: a modell visszaállításához az alapértelmezett értékre, törölje a mezőt és mentse.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Egyedi titkosítási titok használatához (a származtatott wp_salt helyett), adja hozzá ezt a wp-config.php-hoz:','Today'=>'Ma','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'A token fogyasztás funkció, szolgáltató és modell szerint összesítve. Minden sikeres AI hívásnál rögzítve; a Tesztkapcsolat pings szándékosan kizárva, hogy ne torzítsák az összesítést. Az alap táblázat napi összesítést végez — válasszon egy ablakot az alábbiak közül, hogy megtekinthesse.','Tone'=>'Hangvétel','tone'=>'hangnem','Tone:'=>'Hangnem:','Too many AI requests. Please retry in %d seconds.'=>'Túl sok AI kérés. Kérjük, próbálja újra %d másodperc múlva.','Total'=>'Összes','Total tokens'=>'Összes token','Translate'=>'Fordítás','Translate / Revise'=>'Fordítás / Átdolgozás','Translate / Revise block'=>'Blokk fordítás / Átdolgozás','Translate all'=>'Összes fordítása','Translate chunk'=>'Szöveg darab fordítása','Translate Content'=>'Tartalom fordítása','Translate missing'=>'Hiányzó fordítás','Translate page…'=>'Oldal fordítása…','Translated content'=>'Fordított tartalom','Translated Names'=>'Fordított nevek','Translated title'=>'Fordított cím','Translated to:'=>'Fordítva: ','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Fordítva. Ellenőrizze a Webhely Szerkesztőben — a belső hivatkozások, navigációs URL-ek és sablon szlógok nem frissülnek automatikusan.','Translating…'=>'Fordítás folyamatban…','Translation'=>'Fordítás','Translation Caching'=>'Fordítás gyorsítótárazás','Translation found but permalink could not be generated'=>'Fordítás megtalálva, de permalink nem generálható','Translation Limits'=>'Fordítási Határok','Translation Limits & Behavior'=>'Fordítási korlátok és viselkedés','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Fordítási korlátok: irányítsa, mely felhasználói szerepkörök indíthatnak AI fordítást, és állítson be havi tokenkeretet. A keret túllépése esetén az AI hívások szünetelnek a hónap újraindulásáig.','Translation Memory'=>'Fordítási memória','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'A Fordítási memória gyorsítótárazza az AI eredményeket tartalom hash, nyelvpár, szolgáltató és modell szerint. Egy bejegyzés szerkesztése érvényteleníti a gyorsítótár bejegyzését, így a következő fordítási hívás friss eredményt kap.','Translation Memory cleared. %d cached block was removed.'=>'Fordítási memória törölve. %d gyorsítótárazott blokk lett eltávolítva.' . "\0" . 'Fordítási memória törölve. %d gyorsítótárazott blokk lett eltávolítva.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Fordítási memória: az összes lefordított bejegyzést tartja tartalom hash szerint. Törölje, ha minden bejegyzés újrafordítását szeretné kényszeríteni, függetlenül attól, hogy változott-e a tartalmuk.','Translation workflow'=>'Fordítási munkafolyamat','Translation, Content Generator'=>'Fordítás, Tartalom Generátor','Type'=>'Típus','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Eltávolítási viselkedés','Uninstall setting saved.'=>'Eltávolítási beállítás mentve.','unknown error'=>'Ismeretlen hiba','Unknown provider.'=>'Ismeretlen szolgáltató.','Up'=>'Fel','Upload .mo file'=>'Feltöltés .mo fájl','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Feltöltött .mo fájlok felülírják a harmadik féltől származó bővítmények szövegeit adott helyeken — például egy egyedi VikBooking fordítás, amely az "apartman" szót használja a "szoba" helyett. A fájloknak követniük kell a WordPress névkonvenciót: {textdomain}-{locale}.mo (pl. vikbooking-ca.mo). Ezek a feltöltött mappában tárolódnak, és túlélnek bővítményfrissítéseket.','Upload Override'=>'Felülírás feltöltése','URL could not be mapped to a post — check the link target exists'=>'Az URL nem volt hozzárendelve egy bejegyzéshez — ellenőrizze, hogy a link célja létezik-e','URL structure'=>'URL szerkezet','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL-struktúra: útvonal-előtag mód (példa.com/de/) nem igényel szerver módosítást. Alcímszó mód (de.pelda.com) wildcard DNS rekordot, wildcard SSL tanúsítványt és webszerver konfigurációs változtatást igényel — lásd a Szerver beállítási útmutatót.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Használja a lapfüleket az oldal tetején a konfigurációhoz. A Router fül módosításai azonnal érvénybe lépnek; az AI kulcsok és modell beállítások a következő AI kérésre alkalmazódnak.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Felhasználó által kezelt terminológia táblázat nyelvpár szerint. Bejegyzéseket adunk hozzá a fordítási rendszerhez, így az AI következetesen használja a preferált kifejezéseket — kritikus a szakterületi szókincshez ("kWp", "PPA", "összekötő pont"), márkanevekhez, amelyeket nem szabad fordítani, és szabványosított szabályozási kifejezésekhez. Mindkét nyelvi mező opcionális: hagyja üresen a "Forrás nyelv" mezőt, hogy a bejegyzést bármely nyelvről fordítva alkalmazza; hagyja üresen a "Cél nyelv" mezőt, hogy az összes célnyelvre alkalmazza egyszerre.','Using custom meta description.'=>'Egyedi meta leírás használata.','View'=>'Nézet','View built-in default'=>'Alapértelmezett megtekintése','View details'=>'Részletek megtekintése','View Lingua Forge details'=>'Lingua Forge részleteinek megtekintése','Visit plugin site'=>'Plugin oldal meglátogatása','Warning:'=>'Figyelem:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Amikor a hibakereső naplózás engedélyezve van (az alábbi kapcsolóval vagy a wp-config.php fájlban a LINGUAFORGE_AI_DEBUG definícióval), a Fordítás és az FSE sablon fordítási funkciók nyers AI promptokat és válaszokat írnak a lemezre hibakeresés céljából. Használd ezt a részt a kimenet figyelésére, és töröld, miután megvan, amire szükséged van — a fájlok gyorsan növekedhetnek nagy oldalakon. Állítsd be a célkönyvtárat a linguaforge_debug_dir szűrő segítségével.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Amikor engedélyezve van, az első alkalommal látogatók, akiknek nincs nyelvi sütiük és nincs nyelvi előtag a URL-ben, a legközelebbi egyező nyelvi verzióra lesznek átirányítva. Az átirányítás kihagyásra kerül, ha a böngésző preferált nyelve nem az aktív router nyelvek között van. Miután a látogató kiválaszt egy nyelvet a váltó segítségével, a süti felülírja, és a böngésző fejlécét minden jövőbeni látogatásnál figyelmen kívül hagyják.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Melyik modell szintet használja a teljes oldal fordításához. A minőség a fent felsorolt Modellek táblában beállított modellt használja, és ajánlott pontos, hosszabb formátumú fordításokhoz. Csak akkor váltson Könnyűre, ha a sebesség vagy a költség a prioritás, és a tartalom rövid.','WP-CLI reference'=>'WP-CLI referencia','Write AI prompts and responses to disk for troubleshooting'=>'AI promptok és válaszok írása a lemezre hibakereséshez','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Kulcsokat állandóként vagy környezeti változóként is definiálhat (pl. wp-config.php-ban). Ezek a források automatikusan használatba kerülnek, ha nincs adatbázisban tárolt kulcs.','You do not have permission to manage these settings.'=>'Nincs jogosultsága ezeknek a beállításoknak a kezelésére.','You do not have permission to read this post.'=>'Nincs jogosultságod olvasni ezt a bejegyzést.','{n} stale path(s)'=>'{n} elavult útvonal(ak)','— Any source language —'=>'— Bármely forrás nyelv —','— Any target language —'=>'— Bármely cél nyelv —','— Any target —'=>'— Bármely cél —','— Any —'=>'— Bármely —','— auto-detect —'=>'— automatikus felismerés —','— select a language —'=>'— válassz egy nyelvet —','— toggle in Settings → Behavior.'=>'— kapcsoló a Beállítások → Viselkedés alatt.','← Back'=>'← Vissza','↑ Detected from current post'=>'↑ Észlelve a jelenlegi bejegyzésből','↺ Re-translate'=>'↺ Újrafordítás','↺ Refine'=>'↺ Finomítás','↺ Refresh'=>'↺ Frissítés','↺ Refreshing…'=>'↺ Frissítés…','⚠ Borderline'=>'⚠ Határérték','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Nem található <strong>{lang}</strong> bejegyzés. Győződjön meg róla, hogy minden fordított bejegyzés nyelvi metaadata <strong>{lang}</strong>-ra van állítva a Nyelv mezőben.','⚠ No changes'=>'⚠ Nincs változás','⚠ No changes — re-scan?'=>'⚠ Nincs változás — újra szkennelés?','✅ Fixed ({n})'=>'✅ Javítva ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Nincs talált törött link vagy sabloneltérés <strong>{lang}</strong> esetén. Átvizsgált <strong>{scanned}</strong> bejegyzést és oldalt — minden ellenőrzés sikeres. A sablonrészek ( fejléc, lábléc, oldalsáv) nem szerepelnek itt — használja a Sablonrészek javítása gombot ezek külön ellenőrzéséhez.','✅ Template fixed'=>'✅ Sablon javítva','✓ All parts created.'=>'✓ Minden rész létrehozva.','✓ All templates created.'=>'✓ Minden sablon létrehozva.','✓ All translated.'=>'✓ Minden fordítva.','✓ Configured'=>'✓ Beállítva','✓ Connection OK'=>'✓ Kapcsolat rendben','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Tartalom generálva — tekintse meg a felületet a felülvizsgálathoz, finomhangoláshoz és alkalmazáshoz.','✓ Done'=>'✓ Kész','✓ Enabled'=>'✓ Engedélyezve','✓ Good length'=>'✓ Jó hosszúság','✓ In safe storage'=>'✓ Biztonságos tárolásban','✓ Language installed.'=>'✓ Nyelv telepítve.','✓ Links fixed.'=>'✓ Linkek javítva.','✓ Nav refs fixed.'=>'✓ Navigációs hivatkozások javítva.','✓ Parts fixed.'=>'✓ Részek javítva.','✓ Pattern translated.'=>'✓ Minta fordítva.','✓ Refined — review the updated draft above.'=>'✓ Finomhangolva — tekintse meg a fenti frissített vázlatot.','✓ Translation saved'=>'✓ Fordítás mentve','✗ Disabled'=>'✗ Letiltva','✗ Error:'=>'✗ Hiba:','✗ Failed:'=>'✗ Sikertelen:','✗ Not configured'=>'✗ Nincs beállítva','✗ Too long'=>'✗ Túl hosszú','✗ Too short'=>'✗ Túl rövid','❌ Failed'=>'❌ Sikertelen','📄 Wrong template'=>'📄 Helytelen sablon','📍 Stale path (page moved)'=>'📍 Elavult útvonal (oldal áthelyezve)']];
